export default JSON.parse(
  "{\n  \"workId\": \"li-ji\",\n  \"chapter\": {\n    \"id\": \"li-ji_ch-9\",\n    \"workId\": \"li-ji\",\n    \"order\": 9,\n    \"title\": \"禮運\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 12,\n    \"passageIds\": [\n      \"li-ji_ch-9_p-1\",\n      \"li-ji_ch-9_p-2\",\n      \"li-ji_ch-9_p-3\",\n      \"li-ji_ch-9_p-4\",\n      \"li-ji_ch-9_p-5\",\n      \"li-ji_ch-9_p-6\",\n      \"li-ji_ch-9_p-7\",\n      \"li-ji_ch-9_p-8\",\n      \"li-ji_ch-9_p-9\",\n      \"li-ji_ch-9_p-10\",\n      \"li-ji_ch-9_p-11\",\n      \"li-ji_ch-9_p-12\",\n      \"li-ji_ch-9_p-13\",\n      \"li-ji_ch-9_p-14\",\n      \"li-ji_ch-9_p-15\",\n      \"li-ji_ch-9_p-16\",\n      \"li-ji_ch-9_p-17\",\n      \"li-ji_ch-9_p-18\",\n      \"li-ji_ch-9_p-19\",\n      \"li-ji_ch-9_p-20\",\n      \"li-ji_ch-9_p-21\",\n      \"li-ji_ch-9_p-22\",\n      \"li-ji_ch-9_p-23\",\n      \"li-ji_ch-9_p-24\",\n      \"li-ji_ch-9_p-25\",\n      \"li-ji_ch-9_p-26\",\n      \"li-ji_ch-9_p-27\",\n      \"li-ji_ch-9_p-28\",\n      \"li-ji_ch-9_p-29\",\n      \"li-ji_ch-9_p-30\",\n      \"li-ji_ch-9_p-31\",\n      \"li-ji_ch-9_p-32\",\n      \"li-ji_ch-9_p-33\"\n    ],\n    \"tags\": [\n      \"儒家\",\n      \"禮樂\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"li-ji_ch-9_p-1\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 1,\n      \"canonicalText\": \"昔者仲尼與於蠟賓，事畢，出遊於觀之上，喟然而嘆。仲尼之嘆，蓋嘆魯也。言偃在側曰：「君子何嘆？」孔子曰：「大道之行也，與三代之英，丘未之逮也，而有志焉。」大道之行也，天下為公。選賢與能，講信修睦，故人不獨親其親，不獨子其子，使老有所終，壯有所用，幼有所長，矜寡孤獨廢疾者，皆有所養。男有分，女有歸。貨惡其棄於地也，不必藏於己；力惡其不出於身也，不必為己。是故謀閉而不興，盜竊亂賊而不作，故外戶而不閉，是謂大同。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-1_s-1\",\n        \"li-ji_ch-9_p-1_s-2\",\n        \"li-ji_ch-9_p-1_s-3\",\n        \"li-ji_ch-9_p-1_s-4\",\n        \"li-ji_ch-9_p-1_s-5\",\n        \"li-ji_ch-9_p-1_s-6\",\n        \"li-ji_ch-9_p-1_s-7\",\n        \"li-ji_ch-9_p-1_s-8\",\n        \"li-ji_ch-9_p-1_s-9\",\n        \"li-ji_ch-9_p-1_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"昔的人或禮儀規程與道崇高德行與品性修養規範制規範仲尼與於蠟賓，事畢，出遊於觀的上，喟然而且嘆。仲尼的嘆，蓋嘆魯啊。言偃在側說道：「具有道德修養之君子賢士人階層何嘆？」孔孔子先生親自開示教導說道：「大道的行啊，與三代的英，丘未的逮啊，而且有志焉。」大道的行啊，天下為公。選賢與能，講信修睦，所以人不獨親他的親，不獨子他的子，使老有所終，壯有所用，幼有所長，矜寡孤獨廢疾的人或禮儀規程與道崇高德行與品性修養規範制規範，皆有所養。男有分，女有歸。貨惡他的棄於地啊，不必藏於己；力惡他的不出於身啊，不必為己。正因為如此謀閉而且不興，盜竊亂賊而且不作，所以外戶而且不閉，是謂大同。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「昔者仲尼與於蠟賓，事畢，出遊於觀之上，喟然而嘆」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「昔」、「仲」、「尼」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「昔者仲尼與於蠟賓事畢出遊於觀之上喟然而嘆仲尼之嘆」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「仲尼之嘆，蓋嘆魯也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-2\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 2,\n      \"canonicalText\": \"今大道既隱，天下為家，各親其親，各子其子，貨力為己，大人世及以為禮。城郭溝池以為固，禮義以為紀；以正君臣，以篤父子，以睦兄弟，以和夫婦，以設制度，以立田里，以賢勇知，以功為己。故謀用是作，而兵由此起。禹、湯、文、武、成王、周公，由此其選也。此六君子者，未有不謹於禮者也。以著其義，以考其信，著有過，刑仁講讓，示民有常。如有不由此者，在勢者去，眾以為殃，是謂小康。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-2_s-1\",\n        \"li-ji_ch-9_p-2_s-2\",\n        \"li-ji_ch-9_p-2_s-3\",\n        \"li-ji_ch-9_p-2_s-4\",\n        \"li-ji_ch-9_p-2_s-5\",\n        \"li-ji_ch-9_p-2_s-6\",\n        \"li-ji_ch-9_p-2_s-7\",\n        \"li-ji_ch-9_p-2_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今大道既隱，天下為家，各親他的親，各子他的子，貨力為己，大人世及以為禮儀規程與道崇高德行與品性修養規範。城郭溝池以為固，禮儀規程與道崇高德行與品性修養規範正義公道之道義以為紀；以正君臣，以篤父子，以睦兄弟，以和夫婦，以設制度，以立田里，以賢勇知，以功為己。所以謀用是作，而且兵由此起。禹、湯、文、武、成王、周公，由此他的選啊。此六具有道德修養之君子賢士人階層的人或禮儀規程與道崇高德行與品性修養規範制規範，未有不謹於禮儀規程與道崇高德行與品性修養規範的人或禮儀規程與道崇高德行與品性修養規範制規範啊。以著他的正義公道之道義，以考他的信，著有過，刑仁愛慈惠之聖德講讓，示民有常。如有不由此的人或禮儀規程與道崇高德行與品性修養規範制規範，在勢的人或禮儀規程與道崇高德行與品性修養規範制規範去，眾以為殃，是謂小康。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「今大道既隱，天下為家，各親其親，各子其子，貨力為己，大人世及以為禮」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「今」、「大」、「道」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「今大道既隱天下為家各親其親各子其子貨力為己大人世」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「城郭溝池以為固，禮義以為紀」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-3\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 3,\n      \"canonicalText\": \"言偃復問曰：「如此乎禮之急也？」孔子曰：「夫禮，先王以承天之道，以治人之情。故失之者死，得之者生。《詩》曰：『相鼠有體，人而無禮；人而無禮，胡不遄死？』是故夫禮，必本於天，殽於地，列於鬼神，達於喪祭、射御、冠昏、朝聘。故聖人以禮示之，故天下國家可得而正也。」\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-3_s-1\",\n        \"li-ji_ch-9_p-3_s-2\",\n        \"li-ji_ch-9_p-3_s-3\",\n        \"li-ji_ch-9_p-3_s-4\",\n        \"li-ji_ch-9_p-3_s-5\",\n        \"li-ji_ch-9_p-3_s-6\",\n        \"li-ji_ch-9_p-3_s-7\",\n        \"li-ji_ch-9_p-3_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"言偃復問說道：「如此乎禮儀規程與道崇高德行與品性修養規範的急啊？」孔孔子先生親自開示教導說道：「夫禮儀規程與道崇高德行與品性修養規範，先王以承天的道，以治人的情。所以失的的人或禮儀規程與道崇高德行與品性修養規範制規範死，得的的人或禮儀規程與道崇高德行與品性修養規範制規範生。《詩》說道：『相鼠有體，人而且無禮儀規程與道崇高德行與品性修養規範；人而且無禮儀規程與道崇高德行與品性修養規範，胡不遄死？』正因為如此夫禮儀規程與道崇高德行與品性修養規範，必本於天，殽於地，列於鬼神，達於喪祭、射御、冠昏、朝聘。所以聖人以禮儀規程與道崇高德行與品性修養規範示的，所以天下國家可得而且正啊。」。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「言偃復問曰：「如此乎禮之急也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「言」、「偃」、「復」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「言偃復問曰如此乎禮之急也孔子曰夫禮先王以承天之道」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「」孔子曰：「夫禮，先王以承天之道，以治人之情」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-4\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 4,\n      \"canonicalText\": \"言偃復問曰：「夫子之極言禮也，可得而聞與？」孔子曰：「我欲觀夏道，是故之杞，而不足徵也；吾得夏時焉。我欲觀殷道，是故之宋，而不足徵也；吾得坤乾焉。坤乾之義，夏時之等，吾以是觀之。」\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-4_s-1\",\n        \"li-ji_ch-9_p-4_s-2\",\n        \"li-ji_ch-9_p-4_s-3\",\n        \"li-ji_ch-9_p-4_s-4\",\n        \"li-ji_ch-9_p-4_s-5\",\n        \"li-ji_ch-9_p-4_s-6\",\n        \"li-ji_ch-9_p-4_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"言偃復問說道：「夫子的極言禮儀規程與道崇高德行與品性修養規範啊，可得而且聞與？」孔孔子先生親自開示教導說道：「我欲觀夏道，正因為如此的杞，而且不足徵啊；吾得夏時焉。我欲觀殷道，正因為如此的宋，而且不足徵啊；吾得坤乾焉。坤乾的正義公道之道義，夏時的等，吾以是觀的。」。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「言偃復問曰：「夫子之極言禮也，可得而聞與」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「言」、「偃」、「復」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「言偃復問曰夫子之極言禮也可得而聞與孔子曰我欲觀夏」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「」孔子曰：「我欲觀夏道，是故之杞，而不足徵也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-5\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 5,\n      \"canonicalText\": \"夫禮之初，始諸飲食，其燔黍捭豚，污尊而抔飲，蕢桴而土鼓，猶若可以致其敬於鬼神。及其死也，升屋而號，告曰：「皋！某復。」然後飯腥而苴孰。故天望而地藏也，體魄則降，知氣在上，故死者北首，生者南鄉，皆從其初。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-5_s-1\",\n        \"li-ji_ch-9_p-5_s-2\",\n        \"li-ji_ch-9_p-5_s-3\",\n        \"li-ji_ch-9_p-5_s-4\",\n        \"li-ji_ch-9_p-5_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"夫禮儀規程與道崇高德行與品性修養規範的初，始諸飲食，他的燔黍捭豚，污尊而且抔飲，蕢桴而且土鼓，猶若可以致他的敬於鬼神。及他的死啊，升屋而且號，告說道：「皋！某復。」然後飯腥而且苴孰。所以天望而且地藏啊，體魄則降，知氣在上，所以死的人或禮儀規程與道崇高德行與品性修養規範制規範北首，生的人或禮儀規程與道崇高德行與品性修養規範制規範南鄉，皆從他的初。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「夫禮之初，始諸飲食，其燔黍捭豚，污尊而抔飲，蕢桴而土鼓，猶若可以致其敬於鬼神」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「初」、「始」、「諸」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「夫禮之初始諸飲食其燔黍捭豚污尊而抔飲蕢桴而土鼓猶」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「及其死也，升屋而號，告曰：「皋」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-6\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 6,\n      \"canonicalText\": \"昔者先王，未有宮室，冬則居營窟，夏則居橧巢。未有火化，食草木之實、鳥獸之肉，飲其血，茹其毛。未有麻絲，衣其羽皮。後聖有作，然後修火之利，範金合土，以為臺榭、宮室、牖戶，以炮以燔，以亨以炙，以為醴酪；治其麻絲，以為布帛，以養生送死，以事鬼神上帝，皆從其朔。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-6_s-1\",\n        \"li-ji_ch-9_p-6_s-2\",\n        \"li-ji_ch-9_p-6_s-3\",\n        \"li-ji_ch-9_p-6_s-4\",\n        \"li-ji_ch-9_p-6_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"昔的人或禮儀規程與道崇高德行與品性修養規範制規範先王，未有宮室，冬則居營窟，夏則居橧巢。未有火化，食草木的實、鳥獸的肉，飲他的血，茹他的毛。未有麻絲，衣他的羽皮。後聖有作，然後修火的利，範金合土，以為臺榭、宮室、牖戶，以炮以燔，以亨以炙，以為醴酪；治他的麻絲，以為布帛，以養生送死，以事鬼神上帝，皆從他的朔。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「昔者先王，未有宮室，冬則居營窟，夏則居橧巢」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「昔」、「先」、「王」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「昔者先王未有宮室冬則居營窟夏則居橧巢未有火化食草」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「未有火化，食草木之實、鳥獸之肉，飲其血，茹其毛」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-7\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 7,\n      \"canonicalText\": \"故玄酒在室，醴醆在戶，粢醍在堂，澄酒在下。陳其犧牲，備其鼎俎，列其琴瑟管磬鐘鼓，修其祝嘏，以降上神與其先祖。以正君臣，以篤父子，以睦兄弟，以齊上下，夫婦有所。是謂承天之祜。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-7_s-1\",\n        \"li-ji_ch-9_p-7_s-2\",\n        \"li-ji_ch-9_p-7_s-3\",\n        \"li-ji_ch-9_p-7_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以玄酒在室，醴醆在戶，粢醍在堂，澄酒在下。陳他的犧牲，備他的鼎俎，列他的琴瑟管磬鐘鼓，修他的祝嘏，以降上神與他的先祖。以正君臣，以篤父子，以睦兄弟，以齊上下，夫婦有所。是謂承天的祜。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故玄酒在室，醴醆在戶，粢醍在堂，澄酒在下」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「玄」、「酒」、「在」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故玄酒在室醴醆在戶粢醍在堂澄酒在下陳其犧牲備其鼎」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「陳其犧牲，備其鼎俎，列其琴瑟管磬鐘鼓，修其祝嘏，以降上神與其先祖」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-8\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 8,\n      \"canonicalText\": \"作其祝號，玄酒以祭，薦其血毛，腥其俎，孰其殽，與其越席，疏布以冪，衣其浣帛，醴醆以獻，薦其燔炙，君與夫人交獻，以嘉魂魄，是謂合莫。然後退而合亨，體其犬豕牛羊，實其簠簋、籩豆、鉶羹。祝以孝告，嘏以慈告，是謂大祥。此禮之大成也。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-8_s-1\",\n        \"li-ji_ch-9_p-8_s-2\",\n        \"li-ji_ch-9_p-8_s-3\",\n        \"li-ji_ch-9_p-8_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"作他的祝號，玄酒以祭，薦他的血毛，腥他的俎，孰他的殽，與他的越席，疏布以冪，衣他的浣帛，醴醆以獻，薦他的燔炙，君與夫人交獻，以嘉魂魄，是謂合莫。然後退而且合亨，體他的犬豕牛羊，實他的簠簋、籩豆、鉶羹。祝以孝告，嘏以慈告，是謂大祥。此禮儀規程與道崇高德行與品性修養規範的大成啊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「作其祝號，玄酒以祭，薦其血毛，腥其俎，孰其殽，與其越席，疏布以冪，衣其浣帛，醴醆以獻，薦其燔炙，君與夫人交獻，以嘉魂魄，是謂合莫」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「作」、「祝」、「號」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「作其祝號玄酒以祭薦其血毛腥其俎孰其殽與其越席疏布」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「然後退而合亨，體其犬豕牛羊，實其簠簋、籩豆、鉶羹」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-9\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 9,\n      \"canonicalText\": \"孔子曰：「於呼哀哉！我觀周道，幽、厲傷之，吾舍魯何適矣！魯之郊禘，非禮也，周公其衰矣！杞之郊也禹也，宋之郊也契也，是天子之事守也。故天子祭天地，諸侯祭社稷。」\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-9_s-1\",\n        \"li-ji_ch-9_p-9_s-2\",\n        \"li-ji_ch-9_p-9_s-3\",\n        \"li-ji_ch-9_p-9_s-4\",\n        \"li-ji_ch-9_p-9_s-5\",\n        \"li-ji_ch-9_p-9_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孔孔子先生親自開示教導說道：「於呼哀哉！我觀周道，幽、厲傷的，吾舍魯何適矣！魯的郊禘，絕不是禮儀規程與道崇高德行與品性修養規範啊，周公他的衰矣！杞的郊啊禹啊，宋的郊啊契啊，是天子的事守啊。所以天子祭天地，諸侯祭社稷。」。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「孔子曰：「於呼哀哉」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「孔」、「呼」、「哀」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「孔子曰於呼哀哉我觀周道幽厲傷之吾舍魯何適矣魯之郊」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「我觀周道，幽、厲傷之，吾舍魯何適矣」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-10\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 10,\n      \"canonicalText\": \"祝嘏莫敢易其常古，是謂大假。祝嘏辭說，藏於宗祝巫史，非禮也，是謂幽國。醆斝及屍君，非禮也，是謂僭君。冕弁兵革藏於私家，非禮也，是謂脅君。大夫具官，祭器不假，聲樂皆具，非禮也，是謂亂國。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-10_s-1\",\n        \"li-ji_ch-9_p-10_s-2\",\n        \"li-ji_ch-9_p-10_s-3\",\n        \"li-ji_ch-9_p-10_s-4\",\n        \"li-ji_ch-9_p-10_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"祝嘏莫敢易他的常古，是謂大假。祝嘏辭說，藏於宗祝巫史，絕非禮儀規程與道道德修養規範啊，是謂幽國。醆斝及屍君，絕非禮儀規程與道道德修養規範啊，是謂僭君。冕弁兵革藏於私家，絕非禮儀規程與道道德修養規範啊，是謂脅君。卿大夫具官，祭器不假，聲禮樂韶樂皆具，絕非禮儀規程與道道德修養規範啊，是謂亂國。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「祝嘏莫敢易其常古，是謂大假」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「祝」、「嘏」、「莫」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「祝嘏莫敢易其常古是謂大假祝嘏辭說藏於宗祝巫史非禮」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「祝嘏辭說，藏於宗祝巫史，非禮也，是謂幽國」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-11\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 11,\n      \"canonicalText\": \"故仕於公曰臣，仕於家曰僕。三年之喪，與新有昏者，期不使。以衰裳入朝，與家僕雜居齊齒，非禮也，是謂君與臣同國。故天子有田以處其子孫，諸侯有國以處其子孫，大夫有采以處其子孫，是謂制度。故天子適諸侯，必舍其祖朝，而不以禮籍入，是謂天子壞法亂紀。諸侯非問疾吊喪而入諸臣之家，是謂君臣為謔。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-11_s-1\",\n        \"li-ji_ch-9_p-11_s-2\",\n        \"li-ji_ch-9_p-11_s-3\",\n        \"li-ji_ch-9_p-11_s-4\",\n        \"li-ji_ch-9_p-11_s-5\",\n        \"li-ji_ch-9_p-11_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以仕於公說道：臣，仕於家說道：僕。三年的喪，與新有昏的人或禮儀規程與道崇高德行與品性修養規範制規範，期不使。以衰裳入朝，與家僕雜居齊齒，絕不是禮儀規程與道崇高德行與品性修養規範啊，是謂君與臣同國。所以天子有田以處他的子孫，諸侯有國以處他的子孫，卿大夫貴族官員有采以處他的子孫，是謂制度。所以天子適諸侯，必舍他的祖朝，而且不以禮儀規程與道崇高德行與品性修養規範籍入，是謂天子壞法亂紀。諸侯絕不是問疾吊喪而且入諸臣的家，是謂君臣為謔。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故仕於公曰臣，仕於家曰僕」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「仕」、「公」、「臣」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故仕於公曰臣仕於家曰僕三年之喪與新有昏者期不使以」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「三年之喪，與新有昏者，期不使」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-12\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 12,\n      \"canonicalText\": \"是故，禮者君之大柄也，所以別嫌明微，儐鬼神，考制度，別仁義，所以治政安君也。故政不正，則君位危；君位危，則大臣倍，小臣竊。刑肅而俗敝，則法無常；法無常，而禮無列；禮無列，則士不事也。刑肅而俗敝，則民弗歸也，是謂疵國。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-12_s-1\",\n        \"li-ji_ch-9_p-12_s-2\",\n        \"li-ji_ch-9_p-12_s-3\",\n        \"li-ji_ch-9_p-12_s-4\",\n        \"li-ji_ch-9_p-12_s-5\",\n        \"li-ji_ch-9_p-12_s-6\",\n        \"li-ji_ch-9_p-12_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"正因為如此，禮儀規程與道崇高德行與品性修養規範的人或禮儀規程與道崇高德行與品性修養規範制規範君的大柄啊，所以別嫌明微，儐鬼神，考制度，別仁愛慈惠之聖德正義公道之道義，所以治政安君啊。所以政不正，則君位危；君位危，則大臣倍，小臣竊。刑肅而且俗敝，則法無常；法無常，而且禮儀規程與道崇高德行與品性修養規範無列；禮儀規程與道崇高德行與品性修養規範無列，則士人階層不事啊。刑肅而且俗敝，則民弗歸啊，是謂疵國。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「是故，禮者君之大柄也，所以別嫌明微，儐鬼神，考制度，別仁義，所以治政安君也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「是」、「君」、「大」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「是故禮者君之大柄也所以別嫌明微儐鬼神考制度別仁義」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「故政不正，則君位危」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-13\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 13,\n      \"canonicalText\": \"故政者君之所以藏身也。是故夫政必本於天，殽以降命。命降於社之謂殽地，降於祖廟之謂仁義，降於山川之謂興作，降於五祀之謂制度。此聖人所以藏身之固也。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-13_s-1\",\n        \"li-ji_ch-9_p-13_s-2\",\n        \"li-ji_ch-9_p-13_s-3\",\n        \"li-ji_ch-9_p-13_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以政的人或禮儀規程與道崇高德行與品性修養規範制規範君的所以藏身啊。正因為如此夫政必本於天，殽以降命。命降於社的謂殽地，降於祖廟的謂仁愛慈惠之聖德正義公道之道義，降於山川的謂興作，降於五祀的謂制度。此聖人所以藏身的固啊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故政者君之所以藏身也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「政」、「君」、「藏」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故政者君之所以藏身也是故夫政必本於天殽以降命命降」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「是故夫政必本於天，殽以降命」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-14\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 14,\n      \"canonicalText\": \"故聖人參於天地，並於鬼神，以治政也。處其所存，禮之序也；玩其所樂，民之治也。故天生時而地生財，人其父生而師教之：四者，君以正用之，故君者立於無過之地也。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-14_s-1\",\n        \"li-ji_ch-9_p-14_s-2\",\n        \"li-ji_ch-9_p-14_s-3\",\n        \"li-ji_ch-9_p-14_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以聖人參於天地，並於鬼神，以治政啊。處他的所存，禮儀規程與道道德修養規範的序啊；玩他的所禮樂韶樂，民的治啊。所以天生時而且地生財，人他的父生而且師教的：四的人或禮儀規程與道道德修養規範制規範，君以正用的，所以君的人或禮儀規程與道道德修養規範制規範立於無過的地啊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故聖人參於天地，並於鬼神，以治政也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「聖」、「人」、「參」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故聖人參於天地並於鬼神以治政也處其所存禮之序也玩」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「處其所存，禮之序也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-15\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 15,\n      \"canonicalText\": \"故君者所明也，非明人者也。君者所養也，非養人者也。君者所事也，非事人者也。故君明人則有過，養人則不足，事人則失位。故百姓則君以自治也，養君以自安也，事君以自顯也。故禮達而分定，人皆愛其死而患其生。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-15_s-1\",\n        \"li-ji_ch-9_p-15_s-2\",\n        \"li-ji_ch-9_p-15_s-3\",\n        \"li-ji_ch-9_p-15_s-4\",\n        \"li-ji_ch-9_p-15_s-5\",\n        \"li-ji_ch-9_p-15_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以君的人或禮儀規程與道崇高德行與品性修養規範制規範所明啊，絕不是明人的人或禮儀規程與道崇高德行與品性修養規範制規範啊。君的人或禮儀規程與道崇高德行與品性修養規範制規範所養啊，絕不是養人的人或禮儀規程與道崇高德行與品性修養規範制規範啊。君的人或禮儀規程與道崇高德行與品性修養規範制規範所事啊，絕不是事人的人或禮儀規程與道崇高德行與品性修養規範制規範啊。所以君明人則有過，養人則不足，事人則失位。所以百姓則君以自治啊，養君以自安啊，事君以自顯啊。所以禮儀規程與道崇高德行與品性修養規範達而且分定，人皆愛他的死而且患他的生。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故君者所明也，非明人者也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「君」、「明」、「非」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故君者所明也非明人者也君者所養也非養人者也君者所」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「君者所養也，非養人者也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-16\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 16,\n      \"canonicalText\": \"故用人之知去其詐，用人之勇去其怒，用人之仁去其貪。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-16_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以用人的知去他的詐，用人的勇去他的怒，用人的仁愛慈惠之聖德去他的貪。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故用人之知去其詐，用人之勇去其怒，用人之仁去其貪」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「用」、「人」、「知」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故用人之知去其詐用人之勇去其怒用人之仁去其貪」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「故用人之知去其詐，用人之勇去其怒，用人之仁去其貪」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-17\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 17,\n      \"canonicalText\": \"故國有患，君死社稷謂之義，大夫死宗廟謂之變。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-17_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以國有患，君死社稷謂的正義公道之道義，卿大夫貴族官員死宗廟謂的變。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故國有患，君死社稷謂之義，大夫死宗廟謂之變」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「國」、「有」、「患」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故國有患君死社稷謂之義大夫死宗廟謂之變」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「故國有患，君死社稷謂之義，大夫死宗廟謂之變」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-18\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 18,\n      \"canonicalText\": \"故聖人耐以天下為一家，以中國為一人者，非意之也，必知其情，闢於其義，明於其利，達於其患，然後能為之。何謂人情？喜怒哀懼愛惡欲七者，弗學而能。何謂人義？父慈、子孝、兄良、弟弟、夫義、婦聽、長惠、幼順、君仁、臣忠十者，謂之人義。講信修睦，謂之人利。爭奪相殺，謂之人患。故聖人所以治人七情，修十義，講信修睦，尚辭讓，去爭奪，舍禮何以治之？\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-18_s-1\",\n        \"li-ji_ch-9_p-18_s-2\",\n        \"li-ji_ch-9_p-18_s-3\",\n        \"li-ji_ch-9_p-18_s-4\",\n        \"li-ji_ch-9_p-18_s-5\",\n        \"li-ji_ch-9_p-18_s-6\",\n        \"li-ji_ch-9_p-18_s-7\",\n        \"li-ji_ch-9_p-18_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以聖人耐以天下為一家，以中國為一人的人或禮儀規程與道崇高德行與品性修養規範制規範，絕不是意的啊，必知他的情，闢於他的正義公道之道義，明於他的利，達於他的患，然後能為的。何謂人情？喜怒哀懼愛惡欲七的人或禮儀規程與道崇高德行與品性修養規範制規範，弗學而且能。何謂人正義公道之道義？父慈、子孝、兄良、弟弟、夫正義公道之道義、婦聽、長惠、幼順、君仁愛慈惠之聖德、臣忠十的人或禮儀規程與道崇高德行與品性修養規範制規範，謂的人正義公道之道義。講信修睦，謂的人利。爭奪相殺，謂的人患。所以聖人所以治人七情，修十正義公道之道義，講信修睦，尚辭讓，去爭奪，舍禮儀規程與道崇高德行與品性修養規範何以治的？\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故聖人耐以天下為一家，以中國為一人者，非意之也，必知其情，闢於其義，明於其利，達於其患，然後能為之」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「聖」、「人」、「耐」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故聖人耐以天下為一家以中國為一人者非意之也必知其」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「何謂人情」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-19\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 19,\n      \"canonicalText\": \"飲食男女，人之大欲存焉；死亡貧苦，人之大惡存焉。故欲惡者，心之大端也。人藏其心，不可測度也；美惡皆在其心，不見其色也，欲一以窮之，舍禮何以哉？\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-19_s-1\",\n        \"li-ji_ch-9_p-19_s-2\",\n        \"li-ji_ch-9_p-19_s-3\",\n        \"li-ji_ch-9_p-19_s-4\",\n        \"li-ji_ch-9_p-19_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"飲食男女，人的大欲存焉；死亡貧苦，人的大惡存焉。所以欲惡的人或禮儀規程與道崇高德行與品性修養規範制規範，心的大端啊。人藏他的心，不可測度啊；美惡皆在他的心，不見他的色啊，欲一以窮的，舍禮儀規程與道崇高德行與品性修養規範何以哉？\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「飲食男女，人之大欲存焉」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「飲」、「食」、「男」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「飲食男女人之大欲存焉死亡貧苦人之大惡存焉故欲惡者」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「死亡貧苦，人之大惡存焉」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 20,\n      \"canonicalText\": \"故人者，其天地之德，陰陽之交，鬼神之會，五行之秀氣也。故天秉陽，垂日星；地秉陰，竅於山川。播五行於四時，和而後月生也。是以三五而盈，三五而闕。五行之動，迭相竭也，五行、四時、十二月，還相為本也；五聲、六律、十二管，還相為宮也；五味、六和、十二食，還相為質也；五色、六章、十二衣，還相為質也。故人者，天地之心也，五行之端也，食味別聲被色而生者也。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-20_s-1\",\n        \"li-ji_ch-9_p-20_s-2\",\n        \"li-ji_ch-9_p-20_s-3\",\n        \"li-ji_ch-9_p-20_s-4\",\n        \"li-ji_ch-9_p-20_s-5\",\n        \"li-ji_ch-9_p-20_s-6\",\n        \"li-ji_ch-9_p-20_s-7\",\n        \"li-ji_ch-9_p-20_s-8\",\n        \"li-ji_ch-9_p-20_s-9\",\n        \"li-ji_ch-9_p-20_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以人的人或禮儀規程與道崇高德行與品性修養規範制規範，他的天地的崇高德行與品性修養，陰陽的交，鬼神的會，五行的秀氣啊。所以天秉陽，垂日星；地秉陰，竅於山川。播五行於四時，和而且後月生啊。是以三五而且盈，三五而且闕。五行的動，迭相竭啊，五行、四時、十二月，還相為本啊；五聲、六律、十二管，還相為宮啊；五味、六和、十二食，還相為質啊；五色、六章、十二衣，還相為質啊。所以人的人或禮儀規程與道崇高德行與品性修養規範制規範，天地的心啊，五行的端啊，食味別聲被色而且生的人或禮儀規程與道崇高德行與品性修養規範制規範啊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故人者，其天地之德，陰陽之交，鬼神之會，五行之秀氣也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「人」、「天」、「地」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故人者其天地之德陰陽之交鬼神之會五行之秀氣也故天」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「故天秉陽，垂日星」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-21\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 21,\n      \"canonicalText\": \"故聖人作則，必以天地為本，以陰陽為端，以四時為柄，以日星為紀，月以為量，鬼神以為徒，五行以為質，禮義以為器，人情以為田，四靈以為畜。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-21_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"因此古代聖王制定法度與典章制度，必定以天覆地載的博大自然為根本依歸，以陰陽交感的運動變化為起始源頭，以春夏秋冬四時節序的輪轉為運行政事的權衡樞紐，以天上的太陽與周天星辰為規律綱紀，以月亮的晦朔圓缺盈虧作為制定曆法度數的衡量標準，以天地神妙的造化神明為推行教化的親密朋徒，以金木水火土五行之氣為構成萬物的質幹根基，以禮節名分與道德節義作為經緯治國的根本器度，以天下萬民的情感志向作為耕耘施教的肥沃田疇，以麟、鳳、龜、龍這四種靈祥聖獸作為家國蓄養守護的神明。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故聖人作則，必以天地為本，以陰陽為端，以四時為柄，以日星為紀，月以為量，鬼神以為徒，五行以為質，禮義以為器，人情以為田，四靈以為畜」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「聖」、「人」、「作」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故聖人作則必以天地為本以陰陽為端以四時為柄以日星」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「故聖人作則，必以天地為本，以陰陽為端，以四時為柄，以日星為紀，月以為量，鬼神以為徒，五行以為質，禮義以為器，人情以為田，四靈以為畜」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 22,\n      \"canonicalText\": \"以天地為本，故物可舉也；以陰陽為端，故情可睹也；以四時為柄，故事可勸也；以日星為紀，故事可列也；月以為量，故功有藝也；鬼神以為徒，故事有守也；五行以為質，故事可復也；禮義以為器，故事行有考也；人情以為田，故人以為奧也；四靈以為畜，故飲食有由也。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-22_s-1\",\n        \"li-ji_ch-9_p-22_s-2\",\n        \"li-ji_ch-9_p-22_s-3\",\n        \"li-ji_ch-9_p-22_s-4\",\n        \"li-ji_ch-9_p-22_s-5\",\n        \"li-ji_ch-9_p-22_s-6\",\n        \"li-ji_ch-9_p-22_s-7\",\n        \"li-ji_ch-9_p-22_s-8\",\n        \"li-ji_ch-9_p-22_s-9\",\n        \"li-ji_ch-9_p-22_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"以天地為本，所以物可舉啊；以陰陽為端，所以情可睹啊；以四時為柄，所以事可勸啊；以日星為紀，所以事可列啊；月以為量，所以功有藝啊；鬼神以為徒，所以事有守啊；五行以為質，所以事可復啊；禮儀規程與道崇高德行與品性修養規範正義公道之道義以為器，所以事行有考啊；人情以為田，所以人以為奧啊；四靈以為畜，所以飲食有由啊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「以天地為本，故物可舉也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「天」、「地」、「為」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「以天地為本故物可舉也以陰陽為端故情可睹也以四時為」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「以陰陽為端，故情可睹也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-23\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 23,\n      \"canonicalText\": \"何謂四靈？麟鳳龜龍，謂之四靈。故龍以為畜，故魚鮪不淰；鳳以為畜，故鳥不獝；麟以為畜，故獸不狘；龜以為畜，故人情不失。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-23_s-1\",\n        \"li-ji_ch-9_p-23_s-2\",\n        \"li-ji_ch-9_p-23_s-3\",\n        \"li-ji_ch-9_p-23_s-4\",\n        \"li-ji_ch-9_p-23_s-5\",\n        \"li-ji_ch-9_p-23_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"何謂四靈？麟鳳龜龍，謂的四靈。所以龍以為畜，所以魚鮪不淰；鳳以為畜，所以鳥不獝；麟以為畜，所以獸不狘；龜以為畜，所以人情不失。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「何謂四靈」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「何」、「謂」、「四」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「何謂四靈麟鳳龜龍謂之四靈故龍以為畜故魚鮪不淰鳳以」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「麟鳳龜龍，謂之四靈」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-24\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 24,\n      \"canonicalText\": \"故先王秉蓍龜，列祭祀，瘞繒，宣祝嘏辭說，設制度，故國有禮，官有御，事有職，禮有序。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-24_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以先王秉蓍龜，列祭祀，瘞繒，宣祝嘏辭說，設制度，所以國有禮儀規程與道崇高德行與品性修養規範，官有御，事有職，禮儀規程與道崇高德行與品性修養規範有序。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故先王秉蓍龜，列祭祀，瘞繒，宣祝嘏辭說，設制度，故國有禮，官有御，事有職，禮有序」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「先」、「王」、「秉」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故先王秉蓍龜列祭祀瘞繒宣祝嘏辭說設制度故國有禮官」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「故先王秉蓍龜，列祭祀，瘞繒，宣祝嘏辭說，設制度，故國有禮，官有御，事有職，禮有序」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-25\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 25,\n      \"canonicalText\": \"故先王患禮之不達於下也，故祭帝於郊，所以定天位也；祀社於國，所以列地利也；祖廟所以本仁也，山川所以儐鬼神也，五祀所以本事也。故宗祝在廟，三公在朝，三老在學。王，前巫而後史，卜筮瞽侑皆在左右，王中心無為也，以守至正。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-25_s-1\",\n        \"li-ji_ch-9_p-25_s-2\",\n        \"li-ji_ch-9_p-25_s-3\",\n        \"li-ji_ch-9_p-25_s-4\",\n        \"li-ji_ch-9_p-25_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以先王患禮儀規程與道崇高德行與品性修養規範的不達於下啊，所以祭帝於郊，所以定天位啊；祀社於國，所以列地利啊；祖廟所以本仁愛慈惠之聖德啊，山川所以儐鬼神啊，五祀所以本事啊。所以宗祝在廟，三公在朝，三老在學。王，前巫而且後史，卜筮瞽侑皆在左右，王中心無為啊，以守至正。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故先王患禮之不達於下也，故祭帝於郊，所以定天位也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「先」、「王」、「患」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故先王患禮之不達於下也故祭帝於郊所以定天位也祀社」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「祀社於國，所以列地利也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-26\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 26,\n      \"canonicalText\": \"故禮行於郊，而百神受職焉，禮行於社，而百貨可極焉，禮行於祖廟而孝慈服焉，禮行於五祀而正法則焉。故自郊社、祖廟、山川、五祀，義之修而禮之藏也。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-26_s-1\",\n        \"li-ji_ch-9_p-26_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以禮儀規程與道崇高德行與品性修養規範行於郊，而且百神受職焉，禮儀規程與道崇高德行與品性修養規範行於社，而且百貨可極焉，禮儀規程與道崇高德行與品性修養規範行於祖廟而且孝慈服焉，禮儀規程與道崇高德行與品性修養規範行於五祀而且正法則焉。所以自郊社、祖廟、山川、五祀，正義公道之道義的修而且禮儀規程與道崇高德行與品性修養規範的藏啊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故禮行於郊，而百神受職焉，禮行於社，而百貨可極焉，禮行於祖廟而孝慈服焉，禮行於五祀而正法則焉」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「行」、「郊」、「百」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故禮行於郊而百神受職焉禮行於社而百貨可極焉禮行於」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「故自郊社、祖廟、山川、五祀，義之修而禮之藏也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-27\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 27,\n      \"canonicalText\": \"是故夫禮，必本於大一，分而為天地，轉而為陰陽，變而為四時，列而為鬼神。其降曰命，其官於天也。夫禮必本於天，動而之地，列而之事，變而從時，協於分藝，其居人也曰養，其行之以貨力、辭讓：飲食、冠昏、喪祭、射御、朝聘。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-27_s-1\",\n        \"li-ji_ch-9_p-27_s-2\",\n        \"li-ji_ch-9_p-27_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"正因為如此夫禮儀規程與道崇高德行與品性修養規範，必本於大一，分而且為天地，轉而且為陰陽，變而且為四時，列而且為鬼神。他的降說道：命，他的官於天啊。夫禮儀規程與道崇高德行與品性修養規範必本於天，動而且的地，列而且的事，變而且從時，協於分藝，他的居人啊說道：養，他的行的以貨力、辭讓：飲食、冠昏、喪祭、射御、朝聘。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「是故夫禮，必本於大一，分而為天地，轉而為陰陽，變而為四時，列而為鬼神」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「是」、「必」、「本」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「是故夫禮必本於大一分而為天地轉而為陰陽變而為四時」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「其降曰命，其官於天也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-28\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 28,\n      \"canonicalText\": \"故禮義也者，人之大端也，所以講信修睦而固人之肌膚之會、筋骸之束也。所以養生送死事鬼神之大端也。所以達天道順人情之大竇也。故唯聖人為知禮之不可以已也，故壞國、喪家、亡人，必先去其禮。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-28_s-1\",\n        \"li-ji_ch-9_p-28_s-2\",\n        \"li-ji_ch-9_p-28_s-3\",\n        \"li-ji_ch-9_p-28_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以禮儀規程與道崇高德行與品性修養規範正義公道之道義啊的人或禮儀規程與道崇高德行與品性修養規範制規範，人的大端啊，所以講信修睦而且固人的肌膚的會、筋骸的束啊。所以養生送死事鬼神的大端啊。所以達天道順人情的大竇啊。所以唯聖人為知禮儀規程與道崇高德行與品性修養規範的不可以已啊，所以壞國、喪家、亡人，必先去他的禮儀規程與道崇高德行與品性修養規範。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故禮義也者，人之大端也，所以講信修睦而固人之肌膚之會、筋骸之束也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「義」、「人」、「大」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故禮義也者人之大端也所以講信修睦而固人之肌膚之會」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「所以養生送死事鬼神之大端也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-29\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 29,\n      \"canonicalText\": \"故禮之於人也，猶酒之有蘗也，君子以厚，小人以薄。故聖王修義之柄、禮之序，以治人情。故人情者，聖王之田也。修禮以耕之，陳義以種之，講學以耨之，本仁以聚之，播樂以安之。故禮也者，義之實也。協諸義而協，則禮雖先王未之有，可以義起也。義者藝之分、仁之節也，協於藝，講於仁，得之者強。仁者，義之本也，順之體也，得之者尊。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-29_s-1\",\n        \"li-ji_ch-9_p-29_s-2\",\n        \"li-ji_ch-9_p-29_s-3\",\n        \"li-ji_ch-9_p-29_s-4\",\n        \"li-ji_ch-9_p-29_s-5\",\n        \"li-ji_ch-9_p-29_s-6\",\n        \"li-ji_ch-9_p-29_s-7\",\n        \"li-ji_ch-9_p-29_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以禮儀規程與道道德修養規範的於人啊，猶酒的有蘗啊，有德君子人階層以厚，小人以薄。所以聖王修道義的柄、禮儀規程與道道德修養規範的序，以治人情。所以人情的人或禮儀規程與道道德修養規範制規範，聖王的田啊。修禮儀規程與道道德修養規範以耕的，陳道義以種的，講學以耨的，本仁德以聚的，播禮樂韶樂以安的。所以禮儀規程與道道德修養規範啊的人或禮儀規程與道道德修養規範制規範，道義的實啊。協諸道義而且協，則禮儀規程與道道德修養規範雖先王未的有，可以道義起啊。道義的人或禮儀規程與道道德修養規範制規範藝的分、仁德的節啊，協於藝，講於仁德，得的的人或禮儀規程與道道德修養規範制規範強。仁德的人或禮儀規程與道道德修養規範制規範，道義的本啊，順的體啊，得的的人或禮儀規程與道道德修養規範制規範尊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故禮之於人也，猶酒之有蘗也，君子以厚，小人以薄」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「人」、「猶」、「酒」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故禮之於人也猶酒之有蘗也君子以厚小人以薄故聖王修」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「故聖王修義之柄、禮之序，以治人情」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-30\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 30,\n      \"canonicalText\": \"故治國不以禮，猶無耜而耕也；為禮不本於義，猶耕而弗種也；為義而不講之以學，猶種而弗耨也；講之於學而不合之以仁，猶耨而弗獲也；合之以仁而不安之以樂，猶獲而弗食也；安之以樂而不達於順，猶食而弗肥也。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-30_s-1\",\n        \"li-ji_ch-9_p-30_s-2\",\n        \"li-ji_ch-9_p-30_s-3\",\n        \"li-ji_ch-9_p-30_s-4\",\n        \"li-ji_ch-9_p-30_s-5\",\n        \"li-ji_ch-9_p-30_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以治國不以禮儀規程與道道德修養規範，猶無耜而且耕啊；為禮儀規程與道道德修養規範不本於道義，猶耕而且弗種啊；為道義而且不講的以學，猶種而且弗耨啊；講的於學而且不合的以仁德，猶耨而且弗獲啊；合的以仁德而且不安的以禮樂韶樂，猶獲而且弗食啊；安的以禮樂韶樂而且不達於順，猶食而且弗肥啊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故治國不以禮，猶無耜而耕也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「治」、「國」、「不」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故治國不以禮猶無耜而耕也為禮不本於義猶耕而弗種也」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「為禮不本於義，猶耕而弗種也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-31\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 31,\n      \"canonicalText\": \"四體既正，膚革充盈，人之肥也。父子篤，兄弟睦，夫婦和，家之肥也。大臣法，小臣廉，官職相序，君臣相正，國之肥也。天子以德為車、以樂為御，諸侯以禮相與，大夫以法相序，士以信相考，百姓以睦相守，天下之肥也。是謂大順。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-31_s-1\",\n        \"li-ji_ch-9_p-31_s-2\",\n        \"li-ji_ch-9_p-31_s-3\",\n        \"li-ji_ch-9_p-31_s-4\",\n        \"li-ji_ch-9_p-31_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"四體既正，膚革充盈，人的肥啊。父子篤，兄弟睦，夫婦和，家的肥啊。大臣法，小臣廉，官職相序，君臣相正，國的肥啊。天子以道德修養為車、以禮樂韶樂為御，諸侯以禮儀規程與道道德修養規範相與，卿大夫以法相序，士人以信相考，百姓以睦相守，天下的肥啊。是謂大順。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「四體既正，膚革充盈，人之肥也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「四」、「體」、「既」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「四體既正膚革充盈人之肥也父子篤兄弟睦夫婦和家之肥」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「父子篤，兄弟睦，夫婦和，家之肥也」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-32\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 32,\n      \"canonicalText\": \"大順者，所以養生送死、事鬼神之常也。故事大積焉而不苑，並行而不繆，細行而不失。深而通，茂而有間。連而不相及也，動而不相害也，此順之至也。故明於順，然後能守危也。故禮之不同也，不豐也，不殺也，所以持情而合危也。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-32_s-1\",\n        \"li-ji_ch-9_p-32_s-2\",\n        \"li-ji_ch-9_p-32_s-3\",\n        \"li-ji_ch-9_p-32_s-4\",\n        \"li-ji_ch-9_p-32_s-5\",\n        \"li-ji_ch-9_p-32_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"大順的人或禮儀規程與道崇高德行與品性修養規範制規範，所以養生送死、事鬼神的常啊。所以事大積焉而且不苑，並行而且不繆，細行而且不失。深而且通，茂而且有間。連而且不相及啊，動而且不相害啊，此順的至啊。所以明於順，然後能守危啊。所以禮儀規程與道崇高德行與品性修養規範的不同啊，不豐啊，不殺啊，所以持情而且合危啊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「大順者，所以養生送死、事鬼神之常也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「大」、「順」、「養」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「大順者所以養生送死事鬼神之常也故事大積焉而不苑並」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「故事大積焉而不苑，並行而不繆，細行而不失」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-33\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"order\": 33,\n      \"canonicalText\": \"故聖王所以順，山者不使居川，不使渚者居中原，而弗敝也。用水火金木，飲食必時。合男女，頒爵位，必當年德。用民必順。故無水旱昆蟲之災，民無凶饑妖孽之疾。故天不愛其道，地不愛其寶，人不愛其情。故天降膏露，地出醴泉，山出器車，河出馬圖，鳳凰麒麟皆在郊棷，龜龍在宮沼，其餘鳥獸之卵胎，皆可俯而窺也。則是無故，先王能修禮以達義，體信以達順，故此順之實也。\",\n      \"sentenceIds\": [\n        \"li-ji_ch-9_p-33_s-1\",\n        \"li-ji_ch-9_p-33_s-2\",\n        \"li-ji_ch-9_p-33_s-3\",\n        \"li-ji_ch-9_p-33_s-4\",\n        \"li-ji_ch-9_p-33_s-5\",\n        \"li-ji_ch-9_p-33_s-6\",\n        \"li-ji_ch-9_p-33_s-7\",\n        \"li-ji_ch-9_p-33_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《禮記》—中國哲學書電子化計劃\",\n          \"edition\": \"阮元校刻《十三經註疏・禮記正義》\",\n          \"location\": \"https://ctext.org/liji/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《禮記》—維基文庫\",\n          \"edition\": \"鄭玄注・孔穎達疏《禮記正義》\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/禮記\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以聖王所以順，山的人或禮儀規程與道崇高德行與品性修養規範制規範不使居川，不使渚的人或禮儀規程與道崇高德行與品性修養規範制規範居中原，而且弗敝啊。用水火金木，飲食必時。合男女，頒爵位，必當年崇高德行與品性修養。用民必順。所以無水旱昆蟲的災，民無凶饑妖孽的疾。所以天不愛他的道，地不愛他的寶，人不愛他的情。所以天降膏露，地出醴泉，山出器車，河出馬圖，鳳凰麒麟皆在郊棷，龜龍在宮沼，他的餘鳥獸的卵胎，皆可俯而且窺啊。則是無所以，先王能修禮儀規程與道崇高德行與品性修養規範以達正義公道之道義，體信以達順，所以此順的實啊。\",\n        \"analysis\": \"【典籍歷史與經學背景】\\n本節選自儒家禮學總典《禮記》〈禮運〉。三代聖王以禮制治天下，本段開篇「故聖王所以順，山者不使居川，不使渚者居中原，而弗敝也」立論嚴謹，深刻彰顯西周禮樂憲章、宗法倫理與天下教化之神聖經學法度。\\n\\n【名物制度與古訓考釋】\\n依漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》，深入考辨「聖」、「王」、「順」等核心名物儀軌與祭祀服色度數，訓詁精確，明辨吉凶軍賓嘉五禮之精微差別。\\n\\n【章法結構與威儀條理】\\n全節行文進退有度、章法井然，引「故聖王所以順山者不使居川不使渚者居中原而弗敝也用」層層剖析禮度節文，將內在「毋不敬」之真誠敬意化為外在彬彬有禮之君子行止，文質彬彬，展現禮由心生、體現於節奏之典雅風範。\\n\\n【義理教化與文明價值】\\n「用水火金木，飲食必時」深刻揭示禮樂文明天人合一、安頓人心與和諧萬邦之最高哲理追求，超越純粹器物形式，為中華民族構築起延續兩千餘年的禮儀之邦社會道德倫理秩序。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"昔者仲尼與於蠟賓，事畢，出遊於觀之上，喟然而嘆。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"仲尼之嘆，蓋嘆魯也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"言偃在側曰：「君子何嘆？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"」孔子曰：「大道之行也，與三代之英，丘未之逮也，而有志焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"」大道之行也，天下為公。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"選賢與能，講信修睦，故人不獨親其親，不獨子其子，使老有所終，壯有所用，幼有所長，矜寡孤獨廢疾者，皆有所養。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"男有分，女有歸。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-8\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"貨惡其棄於地也，不必藏於己；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-9\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"力惡其不出於身也，不必為己。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-1_s-10\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"是故謀閉而不興，盜竊亂賊而不作，故外戶而不閉，是謂大同。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-2_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"今大道既隱，天下為家，各親其親，各子其子，貨力為己，大人世及以為禮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-2_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"城郭溝池以為固，禮義以為紀；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-2_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"以正君臣，以篤父子，以睦兄弟，以和夫婦，以設制度，以立田里，以賢勇知，以功為己。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-2_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"故謀用是作，而兵由此起。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-2_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"禹、湯、文、武、成王、周公，由此其選也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-2_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"此六君子者，未有不謹於禮者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-2_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"以著其義，以考其信，著有過，刑仁講讓，示民有常。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-2_s-8\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"如有不由此者，在勢者去，眾以為殃，是謂小康。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-3_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"言偃復問曰：「如此乎禮之急也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-3_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"」孔子曰：「夫禮，先王以承天之道，以治人之情。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-3_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"故失之者死，得之者生。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-3_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"《詩》曰：『相鼠有體，人而無禮；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-3_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"人而無禮，胡不遄死？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-3_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"』是故夫禮，必本於天，殽於地，列於鬼神，達於喪祭、射御、冠昏、朝聘。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-3_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"故聖人以禮示之，故天下國家可得而正也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-3_s-8\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-4_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"言偃復問曰：「夫子之極言禮也，可得而聞與？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-4_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"」孔子曰：「我欲觀夏道，是故之杞，而不足徵也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-4_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"吾得夏時焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-4_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"我欲觀殷道，是故之宋，而不足徵也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-4_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"吾得坤乾焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-4_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"坤乾之義，夏時之等，吾以是觀之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-4_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-5_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"夫禮之初，始諸飲食，其燔黍捭豚，污尊而抔飲，蕢桴而土鼓，猶若可以致其敬於鬼神。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-5_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"及其死也，升屋而號，告曰：「皋！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-5_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"某復。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-5_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"」然後飯腥而苴孰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-5_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"故天望而地藏也，體魄則降，知氣在上，故死者北首，生者南鄉，皆從其初。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-6_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"昔者先王，未有宮室，冬則居營窟，夏則居橧巢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-6_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"未有火化，食草木之實、鳥獸之肉，飲其血，茹其毛。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-6_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"未有麻絲，衣其羽皮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-6_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"後聖有作，然後修火之利，範金合土，以為臺榭、宮室、牖戶，以炮以燔，以亨以炙，以為醴酪；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-6_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"治其麻絲，以為布帛，以養生送死，以事鬼神上帝，皆從其朔。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-7_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"故玄酒在室，醴醆在戶，粢醍在堂，澄酒在下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-7_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"陳其犧牲，備其鼎俎，列其琴瑟管磬鐘鼓，修其祝嘏，以降上神與其先祖。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-7_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"以正君臣，以篤父子，以睦兄弟，以齊上下，夫婦有所。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-7_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"是謂承天之祜。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-8_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"作其祝號，玄酒以祭，薦其血毛，腥其俎，孰其殽，與其越席，疏布以冪，衣其浣帛，醴醆以獻，薦其燔炙，君與夫人交獻，以嘉魂魄，是謂合莫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-8_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"然後退而合亨，體其犬豕牛羊，實其簠簋、籩豆、鉶羹。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-8_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"祝以孝告，嘏以慈告，是謂大祥。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-8_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"此禮之大成也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-9_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"孔子曰：「於呼哀哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-9_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"我觀周道，幽、厲傷之，吾舍魯何適矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-9_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"魯之郊禘，非禮也，周公其衰矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-9_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"杞之郊也禹也，宋之郊也契也，是天子之事守也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-9_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"故天子祭天地，諸侯祭社稷。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-9_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-10_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"祝嘏莫敢易其常古，是謂大假。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-10_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"祝嘏辭說，藏於宗祝巫史，非禮也，是謂幽國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-10_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"醆斝及屍君，非禮也，是謂僭君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-10_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"冕弁兵革藏於私家，非禮也，是謂脅君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-10_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"大夫具官，祭器不假，聲樂皆具，非禮也，是謂亂國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-11_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"故仕於公曰臣，仕於家曰僕。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-11_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"三年之喪，與新有昏者，期不使。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-11_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"以衰裳入朝，與家僕雜居齊齒，非禮也，是謂君與臣同國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-11_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"故天子有田以處其子孫，諸侯有國以處其子孫，大夫有采以處其子孫，是謂制度。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-11_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"故天子適諸侯，必舍其祖朝，而不以禮籍入，是謂天子壞法亂紀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-11_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"諸侯非問疾吊喪而入諸臣之家，是謂君臣為謔。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-12_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"是故，禮者君之大柄也，所以別嫌明微，儐鬼神，考制度，別仁義，所以治政安君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-12_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"故政不正，則君位危；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-12_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"君位危，則大臣倍，小臣竊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-12_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"刑肅而俗敝，則法無常；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-12_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"法無常，而禮無列；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-12_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"禮無列，則士不事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-12_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"刑肅而俗敝，則民弗歸也，是謂疵國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-13_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"故政者君之所以藏身也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-13_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"是故夫政必本於天，殽以降命。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-13_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"命降於社之謂殽地，降於祖廟之謂仁義，降於山川之謂興作，降於五祀之謂制度。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-13_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"此聖人所以藏身之固也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-14_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"故聖人參於天地，並於鬼神，以治政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-14_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"處其所存，禮之序也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-14_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"玩其所樂，民之治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-14_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"故天生時而地生財，人其父生而師教之：四者，君以正用之，故君者立於無過之地也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-15_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"故君者所明也，非明人者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-15_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"君者所養也，非養人者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-15_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-15\",\n      \"order\": 3,\n      \"canonicalText\": \"君者所事也，非事人者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-15_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-15\",\n      \"order\": 4,\n      \"canonicalText\": \"故君明人則有過，養人則不足，事人則失位。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-15_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-15\",\n      \"order\": 5,\n      \"canonicalText\": \"故百姓則君以自治也，養君以自安也，事君以自顯也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-15_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-15\",\n      \"order\": 6,\n      \"canonicalText\": \"故禮達而分定，人皆愛其死而患其生。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-16_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"故用人之知去其詐，用人之勇去其怒，用人之仁去其貪。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-17_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"故國有患，君死社稷謂之義，大夫死宗廟謂之變。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-18_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"故聖人耐以天下為一家，以中國為一人者，非意之也，必知其情，闢於其義，明於其利，達於其患，然後能為之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-18_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"何謂人情？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-18_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"喜怒哀懼愛惡欲七者，弗學而能。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-18_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"何謂人義？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-18_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"父慈、子孝、兄良、弟弟、夫義、婦聽、長惠、幼順、君仁、臣忠十者，謂之人義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-18_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"講信修睦，謂之人利。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-18_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"爭奪相殺，謂之人患。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-18_s-8\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-18\",\n      \"order\": 8,\n      \"canonicalText\": \"故聖人所以治人七情，修十義，講信修睦，尚辭讓，去爭奪，舍禮何以治之？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-19_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"飲食男女，人之大欲存焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-19_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"死亡貧苦，人之大惡存焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-19_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"故欲惡者，心之大端也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-19_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-19\",\n      \"order\": 4,\n      \"canonicalText\": \"人藏其心，不可測度也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-19_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-19\",\n      \"order\": 5,\n      \"canonicalText\": \"美惡皆在其心，不見其色也，欲一以窮之，舍禮何以哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"故人者，其天地之德，陰陽之交，鬼神之會，五行之秀氣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"故天秉陽，垂日星；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 3,\n      \"canonicalText\": \"地秉陰，竅於山川。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 4,\n      \"canonicalText\": \"播五行於四時，和而後月生也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 5,\n      \"canonicalText\": \"是以三五而盈，三五而闕。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 6,\n      \"canonicalText\": \"五行之動，迭相竭也，五行、四時、十二月，還相為本也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 7,\n      \"canonicalText\": \"五聲、六律、十二管，還相為宮也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-8\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 8,\n      \"canonicalText\": \"五味、六和、十二食，還相為質也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-9\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 9,\n      \"canonicalText\": \"五色、六章、十二衣，還相為質也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-20_s-10\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-20\",\n      \"order\": 10,\n      \"canonicalText\": \"故人者，天地之心也，五行之端也，食味別聲被色而生者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-21_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-21\",\n      \"order\": 1,\n      \"canonicalText\": \"故聖人作則，必以天地為本，以陰陽為端，以四時為柄，以日星為紀，月以為量，鬼神以為徒，五行以為質，禮義以為器，人情以為田，四靈以為畜。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 1,\n      \"canonicalText\": \"以天地為本，故物可舉也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 2,\n      \"canonicalText\": \"以陰陽為端，故情可睹也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 3,\n      \"canonicalText\": \"以四時為柄，故事可勸也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 4,\n      \"canonicalText\": \"以日星為紀，故事可列也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 5,\n      \"canonicalText\": \"月以為量，故功有藝也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 6,\n      \"canonicalText\": \"鬼神以為徒，故事有守也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 7,\n      \"canonicalText\": \"五行以為質，故事可復也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-8\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 8,\n      \"canonicalText\": \"禮義以為器，故事行有考也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-9\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 9,\n      \"canonicalText\": \"人情以為田，故人以為奧也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-22_s-10\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-22\",\n      \"order\": 10,\n      \"canonicalText\": \"四靈以為畜，故飲食有由也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-23_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-23\",\n      \"order\": 1,\n      \"canonicalText\": \"何謂四靈？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-23_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-23\",\n      \"order\": 2,\n      \"canonicalText\": \"麟鳳龜龍，謂之四靈。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-23_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-23\",\n      \"order\": 3,\n      \"canonicalText\": \"故龍以為畜，故魚鮪不淰；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-23_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-23\",\n      \"order\": 4,\n      \"canonicalText\": \"鳳以為畜，故鳥不獝；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-23_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-23\",\n      \"order\": 5,\n      \"canonicalText\": \"麟以為畜，故獸不狘；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-23_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-23\",\n      \"order\": 6,\n      \"canonicalText\": \"龜以為畜，故人情不失。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-24_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-24\",\n      \"order\": 1,\n      \"canonicalText\": \"故先王秉蓍龜，列祭祀，瘞繒，宣祝嘏辭說，設制度，故國有禮，官有御，事有職，禮有序。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-25_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-25\",\n      \"order\": 1,\n      \"canonicalText\": \"故先王患禮之不達於下也，故祭帝於郊，所以定天位也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-25_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-25\",\n      \"order\": 2,\n      \"canonicalText\": \"祀社於國，所以列地利也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-25_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-25\",\n      \"order\": 3,\n      \"canonicalText\": \"祖廟所以本仁也，山川所以儐鬼神也，五祀所以本事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-25_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-25\",\n      \"order\": 4,\n      \"canonicalText\": \"故宗祝在廟，三公在朝，三老在學。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-25_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-25\",\n      \"order\": 5,\n      \"canonicalText\": \"王，前巫而後史，卜筮瞽侑皆在左右，王中心無為也，以守至正。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-26_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-26\",\n      \"order\": 1,\n      \"canonicalText\": \"故禮行於郊，而百神受職焉，禮行於社，而百貨可極焉，禮行於祖廟而孝慈服焉，禮行於五祀而正法則焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-26_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-26\",\n      \"order\": 2,\n      \"canonicalText\": \"故自郊社、祖廟、山川、五祀，義之修而禮之藏也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-27_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-27\",\n      \"order\": 1,\n      \"canonicalText\": \"是故夫禮，必本於大一，分而為天地，轉而為陰陽，變而為四時，列而為鬼神。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-27_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-27\",\n      \"order\": 2,\n      \"canonicalText\": \"其降曰命，其官於天也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-27_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-27\",\n      \"order\": 3,\n      \"canonicalText\": \"夫禮必本於天，動而之地，列而之事，變而從時，協於分藝，其居人也曰養，其行之以貨力、辭讓：飲食、冠昏、喪祭、射御、朝聘。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-28_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-28\",\n      \"order\": 1,\n      \"canonicalText\": \"故禮義也者，人之大端也，所以講信修睦而固人之肌膚之會、筋骸之束也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-28_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-28\",\n      \"order\": 2,\n      \"canonicalText\": \"所以養生送死事鬼神之大端也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-28_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-28\",\n      \"order\": 3,\n      \"canonicalText\": \"所以達天道順人情之大竇也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-28_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-28\",\n      \"order\": 4,\n      \"canonicalText\": \"故唯聖人為知禮之不可以已也，故壞國、喪家、亡人，必先去其禮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-29_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-29\",\n      \"order\": 1,\n      \"canonicalText\": \"故禮之於人也，猶酒之有蘗也，君子以厚，小人以薄。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-29_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-29\",\n      \"order\": 2,\n      \"canonicalText\": \"故聖王修義之柄、禮之序，以治人情。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-29_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-29\",\n      \"order\": 3,\n      \"canonicalText\": \"故人情者，聖王之田也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-29_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-29\",\n      \"order\": 4,\n      \"canonicalText\": \"修禮以耕之，陳義以種之，講學以耨之，本仁以聚之，播樂以安之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-29_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-29\",\n      \"order\": 5,\n      \"canonicalText\": \"故禮也者，義之實也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-29_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-29\",\n      \"order\": 6,\n      \"canonicalText\": \"協諸義而協，則禮雖先王未之有，可以義起也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-29_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-29\",\n      \"order\": 7,\n      \"canonicalText\": \"義者藝之分、仁之節也，協於藝，講於仁，得之者強。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-29_s-8\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-29\",\n      \"order\": 8,\n      \"canonicalText\": \"仁者，義之本也，順之體也，得之者尊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-30_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-30\",\n      \"order\": 1,\n      \"canonicalText\": \"故治國不以禮，猶無耜而耕也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-30_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-30\",\n      \"order\": 2,\n      \"canonicalText\": \"為禮不本於義，猶耕而弗種也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-30_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-30\",\n      \"order\": 3,\n      \"canonicalText\": \"為義而不講之以學，猶種而弗耨也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-30_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-30\",\n      \"order\": 4,\n      \"canonicalText\": \"講之於學而不合之以仁，猶耨而弗獲也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-30_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-30\",\n      \"order\": 5,\n      \"canonicalText\": \"合之以仁而不安之以樂，猶獲而弗食也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-30_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-30\",\n      \"order\": 6,\n      \"canonicalText\": \"安之以樂而不達於順，猶食而弗肥也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-31_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-31\",\n      \"order\": 1,\n      \"canonicalText\": \"四體既正，膚革充盈，人之肥也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-31_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-31\",\n      \"order\": 2,\n      \"canonicalText\": \"父子篤，兄弟睦，夫婦和，家之肥也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-31_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-31\",\n      \"order\": 3,\n      \"canonicalText\": \"大臣法，小臣廉，官職相序，君臣相正，國之肥也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-31_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-31\",\n      \"order\": 4,\n      \"canonicalText\": \"天子以德為車、以樂為御，諸侯以禮相與，大夫以法相序，士以信相考，百姓以睦相守，天下之肥也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-31_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-31\",\n      \"order\": 5,\n      \"canonicalText\": \"是謂大順。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-32_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-32\",\n      \"order\": 1,\n      \"canonicalText\": \"大順者，所以養生送死、事鬼神之常也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-32_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-32\",\n      \"order\": 2,\n      \"canonicalText\": \"故事大積焉而不苑，並行而不繆，細行而不失。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-32_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-32\",\n      \"order\": 3,\n      \"canonicalText\": \"深而通，茂而有間。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-32_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-32\",\n      \"order\": 4,\n      \"canonicalText\": \"連而不相及也，動而不相害也，此順之至也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-32_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-32\",\n      \"order\": 5,\n      \"canonicalText\": \"故明於順，然後能守危也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-32_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-32\",\n      \"order\": 6,\n      \"canonicalText\": \"故禮之不同也，不豐也，不殺也，所以持情而合危也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-33_s-1\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-33\",\n      \"order\": 1,\n      \"canonicalText\": \"故聖王所以順，山者不使居川，不使渚者居中原，而弗敝也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-33_s-2\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-33\",\n      \"order\": 2,\n      \"canonicalText\": \"用水火金木，飲食必時。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-33_s-3\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-33\",\n      \"order\": 3,\n      \"canonicalText\": \"合男女，頒爵位，必當年德。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-33_s-4\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-33\",\n      \"order\": 4,\n      \"canonicalText\": \"用民必順。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-33_s-5\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-33\",\n      \"order\": 5,\n      \"canonicalText\": \"故無水旱昆蟲之災，民無凶饑妖孽之疾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-33_s-6\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-33\",\n      \"order\": 6,\n      \"canonicalText\": \"故天不愛其道，地不愛其寶，人不愛其情。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-33_s-7\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-33\",\n      \"order\": 7,\n      \"canonicalText\": \"故天降膏露，地出醴泉，山出器車，河出馬圖，鳳凰麒麟皆在郊棷，龜龍在宮沼，其餘鳥獸之卵胎，皆可俯而窺也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"li-ji_ch-9_p-33_s-8\",\n      \"workId\": \"li-ji\",\n      \"chapterId\": \"li-ji_ch-9\",\n      \"passageId\": \"li-ji_ch-9_p-33\",\n      \"order\": 8,\n      \"canonicalText\": \"則是無故，先王能修禮以達義，體信以達順，故此順之實也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
